package com.lianxibu.site.controller.content;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.service.content.OperationAffectedReadService;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.util.List;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class OperationAffectedControllerTest {
 private final Actor owner=new Actor("fictional-owner","owner");private IdentityService auth;private OperationAffectedReadService service;private MockMvc mvc;private ObjectProvider<OperationAffectedReadService> provider;
 @BeforeEach @SuppressWarnings("unchecked") void setup(){auth=mock(IdentityService.class);service=mock(OperationAffectedReadService.class);ObjectProvider<IdentityService> identity=mock(ObjectProvider.class);provider=mock(ObjectProvider.class);when(identity.getIfAvailable()).thenReturn(auth);when(provider.getIfAvailable()).thenReturn(service);when(auth.authenticate("fictional-session")).thenReturn(owner);mvc=MockMvcBuilders.standaloneSetup(new OperationAffectedController(identity,provider)).build();}
 @Test void safeCompleteAndPendingProjectionNoCache()throws Exception{when(service.read(owner,"fictional-operation",null,20)).thenReturn(new OperationAffectedReadService.Page("fictional-operation","complete",1L,List.of(new OperationAffectedReadService.Ref("content","fictional-content",null)),null));mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.operation_ref").value("fictional-operation")).andExpect(jsonPath("$.data.items[0].package_id").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.data.total").value(1));when(service.read(owner,"fictional-operation",null,20)).thenReturn(new OperationAffectedReadService.Page("fictional-operation","pending",null,List.of(),null));mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("pending")).andExpect(jsonPath("$.data.total").value(org.hamcrest.Matchers.nullValue()));}
 @Test void authenticationPrecedesQueryAndStore()throws Exception{mvc.perform(get(path()).param("unknown","fictional")).andExpect(status().isUnauthorized());when(auth.authenticate("fictional-session")).thenReturn(new Actor("fictional-user","user"));mvc.perform(get(path()).cookie(cookie())).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void closedQueryAndCursorFailuresRemainDistinct()throws Exception{mvc.perform(get(path()).cookie(cookie()).param("unknown","fictional")).andExpect(status().isBadRequest());mvc.perform(get(path()).cookie(cookie()).param("limit","1","2")).andExpect(status().isBadRequest());for(String limit:List.of("0","51","-1","01","999999999999999"))mvc.perform(get(path()).cookie(cookie()).param("limit",limit)).andExpect(status().isUnprocessableEntity());mvc.perform(get(path()).cookie(cookie()).param("cursor","")).andExpect(status().isUnprocessableEntity());verifyNoInteractions(service);when(service.read(owner,"fictional-operation","fictional-cursor",1)).thenThrow(new OperationAffectedReadService.CursorConflict());mvc.perform(get(path()).cookie(cookie()).param("cursor","fictional-cursor").param("limit","1")).andExpect(status().isConflict()).andExpect(jsonPath("$.error.code").value("cursor_scope_conflict"));}
 @Test void absentAssemblyMissingCorruptAndUnavailableNeverInventZero()throws Exception{when(provider.getIfAvailable()).thenReturn(null);mvc.perform(get(path()).cookie(cookie())).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1"));when(provider.getIfAvailable()).thenReturn(service);when(service.read(owner,"fictional-operation",null,20)).thenThrow(new OperationAffectedReadService.Missing());mvc.perform(get(path()).cookie(cookie())).andExpect(status().isNotFound());doThrow(new IllegalStateException("Fictional forbidden raw payload")).when(service).read(owner,"fictional-operation",null,20);mvc.perform(get(path()).cookie(cookie())).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.error.message").value("temporarily_unavailable"));doReturn(new OperationAffectedReadService.Page("fictional-other","complete",0L,List.of(),null)).when(service).read(owner,"fictional-operation",null,20);mvc.perform(get(path()).cookie(cookie())).andExpect(status().isServiceUnavailable());}
 private static String path(){return "/admin/operations/fictional-operation/affected";}
 private static jakarta.servlet.http.Cookie cookie(){return new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session");}
}
